/// I muscoli che la figura colora. Il rawValue è l'id di common/muscle-info.ts.
enum MuscleId: String, CaseIterable, Codable {
    case chest
    case deltoids
    case trapezius
    case upperBack
    case lowerBack
    case abs
    case obliques
    case biceps
    case triceps
    case forearm
    case quadriceps
    case adductors
    case tibialis
    case gluteal
    case hamstring
    case calves

    var title: String {
        switch self {
        case .chest: return "Petto"
        case .deltoids: return "Deltoidi"
        case .trapezius: return "Trapezio"
        case .upperBack: return "Schiena alta"
        case .lowerBack: return "Lombari"
        case .abs: return "Addominali"
        case .obliques: return "Obliqui"
        case .biceps: return "Bicipiti"
        case .triceps: return "Tricipiti"
        case .forearm: return "Avambracci"
        case .quadriceps: return "Quadricipiti"
        case .adductors: return "Adduttori"
        case .tibialis: return "Tibiale anteriore"
        case .gluteal: return "Glutei"
        case .hamstring: return "Femorali"
        case .calves: return "Polpacci"
        }
    }

    /// Il gruppo muscolare: il colore del muscolo nella figura.
    var group: MuscleGroup {
        switch self {
        case .chest: return .petto
        case .deltoids: return .spalle
        case .trapezius: return .schiena
        case .upperBack: return .schiena
        case .lowerBack: return .schiena
        case .abs: return .core
        case .obliques: return .core
        case .biceps: return .braccia
        case .triceps: return .braccia
        case .forearm: return .braccia
        case .quadriceps: return .gambe
        case .adductors: return .gambe
        case .tibialis: return .gambe
        case .gluteal: return .gambe
        case .hamstring: return .gambe
        case .calves: return .gambe
        }
    }
}

